INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 13, 'theory', 'Квиз: HTML — документ, семантика и доступность');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 13, 0, 'Зачем нужен атрибут lang у элемента html?', '["Он задаёт кодировку файла","Он меняет шрифт страницы","Он сообщает переводчикам, поисковикам и программам озвучки, на каком языке страница","Он включает режим совместимости со старыми браузерами"]', 2, 'lang не влияет на вид: он помогает выбрать произношение скринридеру, правила переноса и подсказки переводчику. Кодировку задаёт мета-тег charset, а режим разбора — доктайп.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 13, 1, 'Какая последовательность заголовков правильная?', '["Один h1, затем h2, а внутри h2 — h3","Несколько h1 подряд, потому что h1 крупнее","Сначала h1, потом сразу h4, чтобы шрифт был меньше","Только h3: у него удобный размер"]', 0, 'Заголовки — оглавление: один h1, уровни идут по порядку без пропусков. Размер шрифта задают стилями, уровень выбирают по месту в структуре.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 13, 2, 'Зачем к ссылке с target=«_blank» добавляют rel с noopener и noreferrer?', '["Чтобы ссылка открывалась быстрее","Чтобы поисковики не индексировали страницу","Чтобы ссылка превратилась в якорь","Чтобы открытая страница не получила доступ к вашей и не узнала адрес источника"]', 3, 'Без этого страница в новой вкладке могла бы управлять окном-источником через window.opener. Современные браузеры уже подразумевают noopener, но записывать его полезно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 13, 3, 'Какой элемент подходит для главного содержимого страницы?', '["div с классом content","main: он на странице один и даёт скринридеру ориентир","section: их несколько, значит, один из них главный","aside: он всегда посередине"]', 1, 'main отмечает основное содержимое и одновременно служит ориентиром для скринридера; на странице он один. div ничего не сообщает, а aside — побочное содержимое.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 13, 4, 'Что сделает браузер, если абзац не закрыт, а дальше начался новый блок?', '["Покажет сообщение об ошибке и остановит загрузку","Не отобразит страницу вовсе","Закроет абзац сам и построит дерево по правилам разбора из стандарта","Сделает весь остальной текст частью абзаца с мелким шрифтом"]', 2, 'Разбор в HTML описан подробно и прощает ошибки: недостающие теги достраиваются, лишние переставляются. Но структура дерева может оказаться не такой, как вы задумали, поэтому разметку проверяют валидатором.');
